        if (alertBody) alertBody.innerHTML = labels.ocrAlertBody;
        if (cancelBtn) cancelBtn.textContent = labels.ocrAlertCancel;
        if (scanBtnEl) scanBtnEl.textContent = labels.ocrAlertScan;
